contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(amount == 10);
        require(address(this).balance >= amount);

        uint beforePot = c.pot();

        c.play{value: amount}();

        uint afterPot = c.pot();

        // The two possible outcomes of play():
        // - random == 0: pot is paid out and reset to 0
        // - random == 1: pot keeps the newly added ticket amount
        assert(afterPot == 0 || afterPot == beforePot + amount);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint potBefore = c.pot();

        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint potAfter = c.pot();

        if (amount != 10) {
            assert(reverted && potAfter == potBefore);
        } else {
            assert(!reverted && (potAfter == potBefore + 10 || potAfter == 0));
        }
    }

    receive() external payable {}
}

