contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        // If sending Ether, must have enough balance and attach amount as the value.
        // We use a parametric amount to probe both the exact-ticket and non-ticket cases.
        require(address(this).balance >= amount);

        // Record the pot and c's Ether balance before the call.  For a fresh contract pot is 0,
        // but we read the getter so the rule is general over any prior state reachable through c.
        uint potBefore = c.pot();
        uint balBefore = address(c).balance;

        // Top-level call that may revert; it must be reached via try/catch to observe revert status.
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Rule: the call reverts exactly when the attached value differs from the ticket amount (10 wei).
        // Additionally, when it completes with exactly 10 wei, the contract's balance increases by
        // at most 10 wei (the ticket price; pot is zeroed after payout, so the net can be 10) and the pot
        // is either reset to 0 or remains/becomes 10.
        uint potAfter = c.pot();
        uint balAfter = address(c).balance;

        assert(
            (amount != 10 && reverted) ||
            (amount == 10 && !reverted && (potAfter == 0 || potAfter == 10) && balAfter <= balBefore + 10)
        );
    }

    receive() external payable {}
}

